(()=>{'use strict';let revision=0,controller;const status=$('#archive-status'),results=$('#archive-results');
async function load(params){controller?.abort();controller=new AbortController();const response=await fetch('/api/archive?'+new URLSearchParams({...params,collection:$('#archive-collection').value}),{signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Archive unavailable');return data}
async function search(browse=false){const version=++revision;status.textContent='Finding FLAC recordings…';try{const data=await load({q:browse?'':$('#archive-query').value.trim()});if(version!==revision)return;results.innerHTML=data.recordings.map((r,i)=>`<button class="card" data-recording="${i}"><img loading="lazy" src="https://archive.org/services/img/${encodeURIComponent(r.id)}" alt=""><b>${escapeHTML(r.title)}</b><small>${escapeHTML(r.artist)} · ${escapeHTML(r.date)}</small><small>Open FLAC tracks ↗</small></button>`).join('');status.textContent=data.recordings.length?'Select a recording to check its available FLAC tracks.':'No recordings found. Try another artist.';results.querySelectorAll('[data-recording]').forEach(b=>b.onclick=()=>open(data.recordings[Number(b.dataset.recording)]))}catch(e){if(version===revision)status.textContent=e.message}}
async function open(recording){const version=++revision;status.textContent='Checking available FLAC files…';try{const data=await load({id:recording.id});if(version!==revision)return;status.textContent=data.files.length?'Recording ready. Choose a track to play inside Oktawka.':'This recording has no downloadable FLAC tracks. Choose another recording.';modal(`<div class="eyebrow">${data.collection==='open'?'OPEN LABEL ALBUM':'LIVE MUSIC ARCHIVE'} · DIRECT FLAC</div><h2>${escapeHTML(data.title)}</h2><p>${escapeHTML(data.artist)}</p><p class="note">FLAC source files. Bit depth is shown only when verified from the audio header.</p><div id="archive-tracks">${data.files.map((f,i)=>`<button class="cloud-file" data-archive-track="${i}"><span>▶</span><span>${escapeHTML(f.title)}</span><small>FLAC</small></button>`).join('')||'<p>No downloadable FLAC tracks available.</p>'}</div><a href="https://archive.org/details/${encodeURIComponent(recording.id)}" target="_blank" rel="noopener noreferrer">Recording details & sharing policy ↗</a>`);$('#archive-tracks').querySelectorAll('[data-archive-track]').forEach(b=>b.onclick=()=>{const f=data.files[Number(b.dataset.archiveTrack)];let i=tracks.findIndex(t=>t.url===f.url);if(i<0){tracks.push({title:f.title,artist:data.artist||'Live Music Archive',url:f.url,artwork:'https://archive.org/services/img/'+encodeURIComponent(recording.id),sourceCodec:'FLAC',lossless:false,format:'FLAC · bit depth unverified'});i=tracks.length-1}play(i)})}catch(e){if(version===revision)status.textContent=e.message}}
$('#archive-form').onsubmit=e=>{e.preventDefault();search()};$('#archive-browse').onclick=()=>search(true);$('#archive-collection').onchange=()=>{revision++;controller?.abort();results.innerHTML='';status.textContent='Choose Browse recordings or search this collection.'};
})();
